  ov['Catalog'] = { rows: (L.connectors || []).map(c => [c.name, F.title(c.category), (c.authMethods || []).map(a => F.title(a.oAuthGrantType || a.authType)).join(', ') || '—', String(rgBy[srcMeta(c.connectorType).conn] || 0), c.connectionStatus === 'active' ? bg('Connected','success') : bg('Available','info')]),
    note: 'Connectors available to ' + L.tenant.name + ', live from app.demo.fieldwealth.ai. Connected ones open from Connections \u203a Connected.' };
  ov['Clients'] = { rows: clients.map(c => [c.name, c.kind === 'partyGroup' ? 'Household' : F.title(c.kind), c.primaryAdvisor ? c.primaryAdvisor.name : 'Unassigned', String(c.accountCount || 0), F.money(c.value, 2)]),
    note: F.num((t.counts || {}).clients) + ' clients, largest first. Live from app.demo.fieldwealth.ai.' };
