function liveXrMeta(x, cur) {
  const F = FL().fmt;
  return [
    ['CONNECTOR', srcMeta(x.connectorType).conn || x.connectorType, F.short(x.connectionId)],
    ['RUN DATE', F.date(x.runDate), ''],
    ['TRIGGER DATE', F.date(x.triggerDate), ''],
    ['ORIGIN', F.title(x.origin), ''],
    ['RAW STORE TARGET', F.title(x.rawStoreTarget), ''],
    ['DURATION', F.dur(x.createdAt, x.completedAt), ''],
    ['PIPELINE RUN', cur[0], ''],
    ['RECORDS', F.num(x.recordCount), (x.resourcesComplete != null ? x.resourcesComplete + ' of ' + x.resourceCount + ' resources' : '')],
    ['STORAGE PREFIX', x.workflowId || x.id, ''],
  ];
}


/* ---- firms inside a tenant (window.FieldFirms, app/field-firms.js) ---- */
const FF = () => window.FieldFirms || null;
function firmChipVals(tenant) {
  const S = FF();
  if (!S) return { firmChips: [], firmLabel: '' };
  const fs = S.firms(tenant);
  if (fs.length < 2) return { firmChips: [], firmLabel: '' };
  return {
    firmLabel: fs.length + ' firms',
    firmChips: fs.slice(0, 3).map((f, i) => ({ initial: S.initial(f),
      style: 'width:18px; height:18px; border-radius:5px; display:inline-flex; align-items:center; justify-content:center; font-size:9.5px; font-weight:700; color:#fff; background:' + S.color(tenant, f) + '; box-shadow:0 0 0 2px rgb(16,24,38);' + (i ? ' margin-left:-5px;' : '') })),
  };
}
function firmAccessFor(tenant, row, i) {
  const S = FF();
  const fs = S ? S.firms(tenant) : [];
  if (fs.length < 2) return fs[0] ? fs[0].name : '—';
  const role = row[3] && typeof row[3] === 'object' ? row[3].t : String(row[3] || '');
  if (role === 'TenantAdmin' || role === 'Manager') return 'All firms';
  return fs[i % fs.length].name;
}
const PRIMARY_CELL = ' font-weight:600; color:rgb(249,250,251); font-size:13px;';
function primaryCell(out, raw, i) {
  if (i !== 0 || (raw && typeof raw === 'object')) return out;
  return Object.assign({}, out, { style: out.style + PRIMARY_CELL });
}

