        out.cfgInnerStyle = 'position:absolute; top:0; left:0; width:' + CW + 'px; height:' + CH + 'px; transform:scale(' + zoom + '); transform-origin:top left;';
        out.cfgZoomIn = () => this.setState(st => ({ cfgZoom: Math.min(1.6, (st.cfgZoom || 0.6) + 0.15) }));
        out.cfgZoomOut = () => this.setState(st => ({ cfgZoom: Math.max(0.3, (st.cfgZoom || 0.6) - 0.15) }));
        out.cfgZoomFit = () => this.setState({ cfgZoom: 0.6 });
        out.cfgPanRef = (el) => { this._panEl = el; };
        out.cfgPanDown = (e) => {
          const el = this._panEl;
          if (!el) return;
          e.preventDefault();
          this._pan = { x:e.clientX, y:e.clientY, sl:el.scrollLeft, st:el.scrollTop };
          el.style.cursor = 'grabbing';
          el.style.userSelect = 'none';
        };
        out.cfgPanMove = (e) => {
          const el = this._panEl;
          if (!el || !this._pan) return;
          el.scrollLeft = this._pan.sl - (e.clientX - this._pan.x);
          el.scrollTop = this._pan.st - (e.clientY - this._pan.y);
        };
        out.cfgPanUp = () => {
          const el = this._panEl;
          this._pan = null;
          if (el) { el.style.cursor = 'grab'; el.style.userSelect = ''; }
        };
        out.cfgWheel = (e) => {
          const el = this._panEl;
          if (!el) return;
          e.preventDefault();
          const z0 = this.state.cfgZoom || 0.6;
          const z1 = Math.max(0.3, Math.min(1.6, z0 * (e.deltaY < 0 ? 1.12 : 1 / 1.12)));
          if (z1 === z0) return;
          const r = el.getBoundingClientRect();
          const px = (el.scrollLeft + (e.clientX - r.left)) / z0;
          const py = (el.scrollTop + (e.clientY - r.top)) / z0;
          this.setState({ cfgZoom: z1 }, () => {
            el.scrollLeft = px * z1 - (e.clientX - r.left);
            el.scrollTop = py * z1 - (e.clientY - r.top);
          });
        };
