          freshChipStyle: r.fresh && r.fresh !== 'order'
            ? 'display:inline-flex; align-items:center; gap:6px; height:25px; padding:0 10px; border-radius:7px; border:1px solid rgba(0,144,255,0.4); background:rgba(0,144,255,0.12); color:rgb(94,177,239); font-size:11.5px; font-weight:600;'
            : 'display:none;',
