      const EC = E.cols.map(c => c === 'Accts' ? 'Accounts' : c);
      const isNumVal = (v) => typeof v === 'string' && /^[\s$\u2014\-+.,%0-9MBK]+$/.test(v) && /[0-9\u2014]/.test(v);
      const colKind = EC.map((c, j) => {
        const vals = E.rows.map(r => r[j]);
        if (/^(id|cusip|isin)$/i.test(c)) return 'id';
        if (c === '' && vals.every(v => v === '\u203a')) return 'chev';
        if (vals.length && vals.every(v => isNumVal(v))) return 'num';
        if (/date|dob|birth/i.test(c)) return 'date';
        return 'text';
      });
      const PRIMARY = ['Name','Advisor','Party','Description','Ticker'];
      let primaryIdx = EC.findIndex(c => PRIMARY.indexOf(c) !== -1);
      if (primaryIdx < 0) primaryIdx = colKind.findIndex(k => k === 'text');
      out.entCols = EC.map((c, j) => ({ label: c, style: 'white-space:nowrap; overflow:hidden; text-overflow:ellipsis;' + (colKind[j] === 'num' || colKind[j] === 'chev' ? ' text-align:right;' : '') }));
      const entCell = (c, j) => {
        if (c && typeof c === 'object') return cell(c);
        const k = colKind[j];
        const base = 'overflow:hidden; text-overflow:ellipsis; white-space:nowrap; font-variant-numeric:tabular-nums;';
        if (k === 'chev') return { text:'', icon:'fa-solid fa-chevron-right', style:'justify-self:end; color:rgb(107,114,128);' };
        if (k === 'id') return { text:c, style: base + " font-family:'Geist Mono',monospace; font-size:11.5px; color:rgb(163,163,163);" };
        if (j === primaryIdx) return { text:c, style: base + ' font-size:13px; font-weight:600; color:rgb(249,250,251);' };
        if (k === 'num') return { text:c, style: base + ' text-align:right; font-size:13px; color:rgb(249,250,251);' };
        return { text:c, style: base + ' font-size:13px; color:' + (c === '\u2014' ? 'rgb(107,114,128)' : 'rgb(209,213,219)') + ';' };
      };
