  centerNode(id) {
    const nudge = () => {
      const el = this._panEl, t = document.querySelector('[data-node="' + id + '"]');
      if (!el || !t) return;
      const r = t.getBoundingClientRect(), b = el.getBoundingClientRect();
      el.scrollLeft += (r.left - b.left) - (b.width / 2 - r.width / 2);
      el.scrollTop += (r.top - b.top) - (b.height / 2 - r.height / 2);
    };
    [120, 420, 900].forEach(ms => setTimeout(nudge, ms));
  }

  openNodeFix(id) {
    this.setState({ section:'Configuration', group:'pipeline', view:'generic', cfgOpen:'Mock Salesforce, Orion and Schwab', cfgTab:'JSON', connDrill:null, cfgZoom:1.15, cfgFocus:id, cfgApplied:false, cfgRef:null, cfgLegend:false, cfgVerSel:null, cfgDiff:true });
      const nudge = () => {
      const el = this._panEl, t = document.querySelector('[data-node="' + id + '"]');
      if (!el || !t) return;
      const r = t.getBoundingClientRect(), b = el.getBoundingClientRect();
      const usable = b.width;
      el.scrollLeft += (r.left - b.left) - (usable / 2 - r.width / 2);
      el.scrollTop += (r.top - b.top) - (b.height / 2 - r.height / 2);
      let p = el.parentElement;
      while (p) {
        const st = getComputedStyle(p).overflowY;
        if ((st === 'auto' || st === 'scroll') && p.scrollHeight > p.clientHeight + 4) {
          const pb = p.getBoundingClientRect();
          p.scrollTop += (el.getBoundingClientRect().top - pb.top) - 12;
          break;
        }
        p = p.parentElement;
      }
      };
      [120, 420, 900].forEach(ms => setTimeout(nudge, ms));
  }

  startRun() {
    (this._simT || []).forEach(t => clearTimeout(t));
    this._simT = [];
    this.setState({ run:'live-8f21c4', runTab:'Workflows', simStage:0, simFix:{}, runDetail:true, xr:null });
    [1200,2100,3000,3900,4800,5600].forEach((ms, i) => {
      this._simT.push(setTimeout(() => this.setState({ simStage: i + 1 }), ms));
    });
  }

  componentDidMount() {
    this._liveOff = window.FieldLive ? window.FieldLive.on(() => this.forceUpdate()) : null;
    this._firmsOff = window.FieldFirms ? window.FieldFirms.on(() => this.forceUpdate()) : null;
    window.addEventListener('tilestudio:ready', this._tsReady = () => this.forceUpdate());
    this._measureGraph = () => {
      const wf = document.querySelector('[data-wf-cell]');
      if (wf && (this._wfN || 0) < 12) {
        const ww = Math.round(wf.clientWidth);
        if (ww && Math.abs(ww - (this.state.wfW || 0)) > 24) { this._wfN = (this._wfN || 0) + 1; this.setState({ wfW: ww }); }
      }
      const el = document.querySelector('[data-graph-cell]');
      if (!el) return;
      const w = Math.round(el.clientWidth);
      if (w && w !== this.state.graphW) this.setState({ graphW: w });
    };
    window.addEventListener('resize', this._measureGraph);
    this._measureGraph();
    window.addEventListener('conn:drill', this._connDrill = (e) => this.setState({ connDrill: e.detail }));
    window.addEventListener('conn:openEntity', this._connEnt = (e) => {
      const nm = (e.detail && e.detail.name) || '';
      let idx = PEOPLE.findIndex(p => p[1] === nm);
      if (idx < 0) idx = Math.abs(nm.length * 7) % PEOPLE.length;
      this.setState({ view:'generic', group:'data', section:'Entities', entity:'People', entRow: idx, entTab:'Relationships', connDrill: null });
    });
  }
  componentDidUpdate() {
    if (this._measureGraph) this._measureGraph();
  }
  componentWillUnmount() {
    if (this._liveOff) this._liveOff();
    if (this._firmsOff) this._firmsOff();
    window.removeEventListener('tilestudio:ready', this._tsReady);
    window.removeEventListener('resize', this._measureGraph);
    window.removeEventListener('conn:drill', this._connDrill);
    window.removeEventListener('conn:openEntity', this._connEnt);
  }

